try:
    print('>>> x = 2.3456')
    print('>>> y = bytearray()')
    print('>>> x %= y')
    print('>>> x')
    x = 2.3456
    y = bytearray()
    x %= y
    print(x)
except Exception as e:
    print(type(e), ':', e)
print()
